def find_desc(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == 'description' or k == 'descriptionText' or k == 'longDescription':
                print(f"FOUND DESC at {path}.{k}: {json.dumps(v, indent=2)[:5000]}")
                return
            if k in ['ownerText', 'ownerSubtitles', 'longBylineText', 'shortBylineText', 'author', 'channelId']:
                print(f"FOUND KEY {path}.{k}: {json.dumps(v, indent=2)[:1000]}")
            find_desc(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_desc(v, f"{path}[{i}]")

# Also search for 'description' at root level
def search_desc(obj):
    if isinstance(obj, dict):
        for k in obj:
            if 'desc' in k.lower() or 'description' in k.lower():
                print(f"KEY: {k} = {json.dumps(obj[k], indent=2)[:3000]}")
        for v in obj.values():
            search_desc(v)
    elif isinstance(obj, list):
        for v in obj:
            search_desc(v)

