import re, json

with open('/tmp/yt_search2.html', 'r') as f:
    html = f.read()

# Extract ytInitialData
m = re.search(r'var ytInitialData\s*=\s*(\{.*?\});\s*</script>', html, re.DOTALL)
if m:
    data = json.loads(m.group(1))
    # Parse search results
    def parse_results(obj, results=None):
        if results is None:
            results = []
        if isinstance(obj, dict):
            if 'videoId' in obj and 'title' in obj:
                vid = obj['videoId']
                title = obj['title'].get('runs', [{}])[0].get('text', '')
                channel = ''
                # Find channel from byline
                if 'longBylineText' in obj:
                    channel = obj['longBylineText'].get('runs', [{}])[0].get('text', '')
                elif 'shortBylineText' in obj:
                    channel = obj['shortBylineText'].get('runs', [{}])[0].get('text', '')
                results.append((vid, title, channel))
            for v in obj.values():
                parse_results(v, results)
        elif isinstance(obj, list):
            for v in obj:
                parse_results(v, results)
        return results

    entries = parse_results(data)
    # Deduplicate by videoId
    seen = set()
    for vid, title, channel in entries:
        if vid not in seen:
            seen.add(vid)
            if 'Jin Lyrics' in channel or 'Top hits 2024' in title or 'Playlist Hits' in title:
                print(f'VID={vid} | TITLE={title} | CHANNEL={channel}')
else:
    print('No ytInitialData found')
